/**
 * @summary Creates a form that consists of multiple form groups specific to an address form
 *
 * @name address
 * @selector .slds-form-element_address
 * @restrict .slds-form-element_compound, .slds-form_compound
 * @support dev-ready
 * @variant
 */
.slds-form-element_address {

  .slds-form-element__row {
    align-items: baseline;
  }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Creates layout for a form element
 * @name base
 * @selector .slds-form-element
 * @restrict div, fieldset, li
 * @support dev-ready
 * @variant
 */
.slds-form-element {
  position: relative;
  min-width: 0;
}

/**
 * @summary Creates label styles for our form elements
 * @selector .slds-form-element__label
 * @restrict .slds-form-element label, .slds-form-element span, .slds-form-element legend, .slds-form-element div, [class*='slds-checkbox'] span, [class*='slds-radio'] span
 */
.slds-form-element__label {
  @include hyphenate;
  display: inline-block;
  color: var(--slds-g-color-neutral-base-30, #{$color-text-label});
  font-size: $form-label-font-size;
  padding-right: 0;
  padding-top: $spacing-xx-small;
  margin-right: $spacing-x-small;
  margin-bottom: $spacing-xxx-small;

  @include rtl() {
    /*! @noflip */
    margin-right: 0;
    padding-right: 0;

    /*! @noflip */
    margin-left: $spacing-x-small;
    padding-left: 0;
  }

  &:empty {
    margin: 0;
  }
}

/**
 * @summary Wrapper to any form display element
 * @selector .slds-form-element__control
 * @restrict .slds-form-element div
 */
.slds-form-element__control {
  // This clear:left is due to the label of the form element being set to float: left since we don't know if the help-text icon is present in the DOM. Since legend elements can only be floated to modify layout to accommodate the help-text icon, we need to make sure the control stacks below the label by default
  clear: left;
  position: relative;

  @include rtl() {
    /*! @noflip */
    clear: right;
  }

  // Force radios and checkboxes to be on own line when there are multiples in a group
  .slds-radio,
  .slds-checkbox {
    display: block;
  }
}

/**
 * @summary When an icon sits within a form element wrapper and adjacent to another element inside that wrapper such as a .form-element__label
 * @selector .slds-form-element__icon
 * @restrict .slds-form-element div
 */
.slds-form-element__icon {
  display: inline-block;
  position: relative; // Since this container can have a tooltip
  padding-top: $spacing-xx-small;
  vertical-align: top;
  line-height: $line-height-reset;
  z-index: 1; // Helps ensure the help-text icon is clickable in all implementations

  .slds-button_icon {
    position: relative; // Resetting position since the edit button icon to invoke inline-edit is set to position: absolute
  }
}

/**
 * @summary Creates inline help styles, sits below .form-element__control
 * @selector .slds-form-element__help
 * @restrict .slds-form-element div
 */
.slds-form-element__help,
.slds-form-element__helper {
  font-size: $font-size-2;
  margin-top: $spacing-xxx-small;
  display: block;
}

/**
 * @summary Modifier on slds-form-element that it needs to reserve space for the inline-edit trigger button
 * @selector .slds-form-element_edit
 * @restrict .slds-form-element
 */
.slds-form-element_edit,
.slds-form-element--edit {

  .slds-form-element__static {
    width: calc(100% - #{$square-icon-small-boundary}); // Leave space for edit icon
  }
}

/**
 * @summary When a form element is in view mode, we modify some styling
 * @selector .slds-form-element_readonly
 * @restrict .slds-form-element
 */
.slds-form-element_readonly {
  border-bottom: $border-width-thin solid var(--slds-g-color-border-base-1, #{$color-border});
  margin-bottom: 0;

  .slds-form-element__control {
    padding-top: $spacing-xxx-small;
    padding-bottom: $spacing-xxx-small;
    // Heads up: no touch-device() min-height is intended per design which deviates from touch input height system
  }

  // We want no spacing in read only and allow line-height to handle white-space
  .slds-form-element__label {
    margin-bottom: 0;
  }
}

/**
 * @summary The form element label when applied to a legend element
 * @selector .slds-form-element__legend
 * @restrict .slds-form-element legend, .slds-form-element span
 */
.slds-form-element__legend {
  font-weight: $font-weight-bold;
  float: left; // Required to be float: left to accommodate for help-text icon

  @include rtl() {
    /*! @noflip */
    float: right;

    /*! @noflip */
    padding-right: 0;
  }
}

/**
 * @summary Fixed text that sits to the left or right of an input
 * @selector .slds-form-element__addon
 * @restrict .slds-form-element span
 */
.slds-form-element__addon {
  display: inline-block;
  margin: 0 $spacing-x-small;
  align-self: center;
}

/**
 * @summary Read-only components are used to display immutable data within a form
 * @summary Initializes read-only form element
 * @selector .slds-form-element__static
 * @restrict .slds-form-element span, .slds-form-element div
 */
.slds-form-element__static {
  @include break-word;
  display: inline-block;
  font-size: $input-static-font-size;
  font-weight: $input-static-font-weight;
  color: var(--slds-g-color-neutral-base-10, #{$input-static-color});
  width: 100%;

  &.slds-text-longform *:last-child {
    margin-bottom: 0;
  }

  &:empty {
    min-height: calc(#{$var-font-size-7} + 1px); // 22px|20px + 1px
    vertical-align: bottom;
  }

  /**
   * @summary Inline Edit on static form element
   * @selector .slds-form-element__static_edit
   * @restrict .slds-form-element__static
   * @deprecated
   */
  &_edit,
  &--edit {
    width: calc(100% - #{$square-icon-small-boundary}); // Leave space for edit icon
  }
}

/**
 * @summary Required asterisk
 * @selector .slds-required
 * @restrict .slds-form-element abbr, abbr
 */
.slds-required {
  color: var(--slds-g-color-error-base-40, #{$color-text-error});
  margin: 0 $spacing-xxx-small;
}

/**
 * @summary Error styles for form element
 * @selector .slds-has-error
 * @restrict .slds-form-element
 * @modifier
 * @group feedback
 */
.slds-has-error {

  .slds-form-element__help {
    color: var(--slds-g-color-error-base-40, #{$color-text-error});
  }
}

// Lightning Design System 2.264.1
.slds-form-element__label {
  @include flex-vertical-center(inline-flex);
  min-height: $height-tappable-small;
  padding-top: 0;
  padding-right: 0;
  margin-bottom: 0;
  font-size: $font-size-4;
}

// This is a workaround for our current DOM structure and dealing with custom elements, it's not perfect
// but it's a solution that doesn't require CSS combinators and works within our limits. Issue cropped
// up with our help icon next to a label.
.slds-form-element__icon .slds-button_icon {
  // Resize height of our button icons in form elements...
  height: $height-tappable-small;

  // ...unless that icon is being used in a form control and should have a larger tap target
  .slds-form-element__control & {
    height: $height-tappable;
  }
}

.slds-form-element__icon {
  padding-top: 0; // Padding deprecated with increased touch target area size
}

.slds-form-element_edit,
.slds-form-element--edit {

  .slds-form-element__static {
    width: calc(100% - #{$square-tappable});
  }
}

.slds-form-element_readonly {

  .slds-icon {
    @include square($square-tappable-x-small);
  }
}

.slds-form-element__static {
  font-size: $font-size-5;
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Creates a form that consists of multiple form groups
 *
 * @name compound
 * @selector .slds-form-element_compound
 * @restrict .slds-form-element
 * @support dev-ready
 * @variant
 * @lwc
 */
.slds-form-element_compound {

  .slds-form-element__row {
    display: flex;
    margin-bottom: $spacing-xx-small;
    margin-left: ($spacing-xx-small * -1);
    margin-right: ($spacing-xx-small * -1);

    .slds-form-element__label {
      padding-top: 0;
    }
  }

  .slds-form-element {
    /* Internal examples may have incorrectly offset dropdowns, this will need to be fixed, not an issue
     * of this padding implementation.
     */
    padding-left: $spacing-xx-small;
    padding-right: $spacing-xx-small;
  }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Horizontal form elements with label left-aligned to the control
 * @name horizontal
 * @selector .slds-form-element_horizontal
 * @restrict .slds-form-element
 * @support dev-ready
 * @variant
 * @lwc
 */
.slds-form-element_horizontal,
.slds-form_horizontal .slds-form-element,
.slds-form_stacked .slds-form-element_horizontal {
  display: block;

  &:not(.slds-form-element_readonly) {
    margin-bottom: $spacing-x-small;
  }

  // If form element doesn't have a size modifier, make sure it takes up 100% of the parents width
  &:not([class*="slds-size"]) {
    width: 100%;
    flex-basis: 100%;
  }

  // When not editing, view mode, add some buffer to the form element
  &:not(.slds-is-editing) {
    padding: $var-spacing-xx-small $spacing-xx-small;
  }

  // Handle nested form elements due to slotting
  .slds-form-element {
    padding: 0;
    margin-bottom: 0;
  }

  // Need to give space for undo button if in horizontal mode
  &.slds-is-edited {
    padding-top: $square-icon-utility-medium;
  }

  // When form element is in 1 column when other form elements are 2 columns, re-align the label and controls
  &.slds-form-element_1-col {
    @include mq-medium-min {

      .slds-form-element__label {
        // Calculation - 33% of 50% minus help text icon size
        max-width: calc((50% - 33.333%) - #{$square-icon-utility-medium});
      }

      .slds-form-element__control {
        // Calculation - 33% of 50% minus form element horizontal padding
        padding-left: calc((50% - 33.333%) - (#{$spacing-xx-small} * 2));
      }

      .slds-form-element__help {
        margin-left: calc((50% - 33.333%) - (#{$spacing-xx-small} * 2));
      }

      .slds-input-has-icon_left .slds-input__icon {
        left: calc((50% - 33.333%) + #{$spacing-xx-small});
      }
    }
  }

  @include mq-medium-min {
    // Handle label - default behavior
    .slds-form-element__label {
      float: left;
      max-width: calc(33% - #{$square-icon-utility-medium}); // Removing the width of the icon for when the help-text icon is present
      flex-basis: calc(33% - #{$square-icon-utility-medium}); // Some form element controls are set to display:flex
      margin-bottom: 0;
      position: relative;
      z-index: 1;
    }

    // Handle control - default behavior
    .slds-form-element__control {
      padding-left: 33%;
      clear: none; // Reset clear: left when switching to horizontal form layout

      .slds-form-element__control {
        padding-left: 0; // Remove left padding on nested form controls, due to issues related to lightning-form components
      }
    }

    // Help text button icon
    .slds-form-element__icon {
      float: left;
      padding-top: $spacing-xx-small;
    }

    // Handle checkbox
    .slds-checkbox_standalone {
      padding: $spacing-xx-small 0;
    }

    // Since the HTML differs for checkbox and radio groups, adjust the display behavior
    .slds-checkbox:not(.slds-checkbox_stacked),
    .slds-radio {

      .slds-form-element__label {
        position: relative;
        float: none;
        max-width: 100%;
        width: auto;
      }
    }

    // Reset label and control inside of compound fields
    .slds-form-element__row .slds-form-element__label,
    .slds-form-element__row .slds-form-element__control,
    .slds-dueling-list__column .slds-form-element__label {
      width: auto;
      max-width: 100%;
      flex-basis: auto;
      float: none;
      position: relative;
      padding-left: 0;
      margin-bottom: 0;
    }

    .slds-dueling-list {
      clear: none; // Remove backward compatible support
    }

    // Handle inputs with left icon
    .slds-input-has-icon_left {

      .slds-input__icon {
        left: calc(33% + #{$spacing-small});
      }
    }

    .slds-input-has-icon_left-right {

      .slds-input__icon_left {
        left: calc(33% + #{$spacing-small});
      }
    }
  }

  // Position the inline help text correctly when in horizontal/compact layout
  .slds-form-element__help {
    margin-left: 33%;
  }
}

// Bugfix: Avoid a bug where longer length labels may overlap with form element below
// - Ensure the form element is cleared to reset the `float: left` of the label within the form element
// - Cannot use `&.slds-form-element` in the main block above, because of `.slds-form_horizontal .slds-form-element,`
.slds-form-element_horizontal.slds-form-element,
.slds-form_horizontal .slds-form-element,
.slds-form_stacked .slds-form-element_horizontal.slds-form-element {
  @include mq-medium-min {
    @include clearfix;
  }
}


.slds-form-element__control:has(.slds-form-element__control) {
  .slds-form-element__help {
    margin-left: 0;
  }

  @include mq-medium-min {
    .slds-input-has-icon_left .slds-input__icon {
      left: $spacing-small;
    }
  }
}

// Lightning Design System 2.264.1
.slds-form-element_horizontal,
.slds-form_horizontal .slds-form-element,
.slds-form_stacked .slds-form-element_horizontal {
  @include mq-medium-min {

    // Handle label - default behavior
    .slds-form-element__label {
      display: block; // Don't need flex behavior for horizontal variant
      max-width: calc(33% - #{$square-tappable}); // Remove the width of touch icon dimensions
      flex-basis: calc(33% - #{$square-tappable}); // Remove the width of touch icon dimensions
      padding-top: $spacing-xx-small;
    }

    // Handle control - default behavior
    .slds-form-element__control {
      display: block; // Flex behavior is not needed for horizontal variant
      min-height: 0; // Min-height only needed for stacked vertical rhythm
    }

    // Help text button icon
    .slds-form-element__icon {
      padding-top: 0; // Icon size is larger in touch, don't need extra spacing
    }

    .slds-checkbox__label {
      display: block; // Horizontal variant doesn't need vertical centering / Messes up .slds-form-element__label width
    }
  }

  .slds-button_icon {
    vertical-align: top; // Makes our vertical spacing more predictable in horizontal variant
  }
}

