/**
 * @summary Creates layout for a form
 * @name record-detail
 * @selector .slds-form
 * @restrict div, form
 * @support dev-ready
 * @variant
 * @lwc
 */

/**
 * @summary Each row inside of a record form
 * @selector .slds-form__row
 * @restrict .slds-form div
 */
.slds-form__row {
  display: flex;
  flex-wrap: wrap;
  margin-left: ($spacing-small * -1);
  margin-right: ($spacing-small * -1);
}

/**
 * @summary Each item inside of a record form row
 * @selector .slds-form__item
 * @restrict .slds-form__row div
 */
.slds-form__item {
  display: flex;
  flex: 1 1 0%;
  min-width: 280px; // Since container is set to wrap, we'll use flexbox to mimic container query
  padding-left: $spacing-small;
  padding-right: $spacing-small;
}

// min-width of input 280px + 24px left/right padding of the layout = 304px
@media (max-width: 304px) {
  .slds-form__item {
   min-width: 0;
   width: 100%;
   flex: unset;
 }
}

/**
 * @summary Indicates if a form element has been edited, but unsaved
 * @selector .slds-is-edited
 * @restrict .slds-form div
 */
.slds-is-edited {
  background: var(--slds-g-color-palette-yellow-90, #{$color-background-highlight});

  // Move undo button icon to align with form elements
  .slds-form-element__undo {
    top: ($square-icon-utility-medium * -1);
    right: $spacing-xx-small;
  }
}

/**
 * @summary Container for the undo button icon found inside of slds-form-element
 * @selector .slds-form-element__undo
 * @restrict .slds-form-element div
 */
.slds-form-element__undo {
  position: absolute;
  top: 0;
  right: 0;
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Vertical form elements with label stacked on top of control
 * @name stacked
 * @selector .slds-form-element_stacked
 * @restrict .slds-form-element
 * @support dev-ready
 * @variant
 * @lwc
 */
.slds-form-element_stacked,
.slds-form_stacked .slds-form-element,
.slds-form_horizontal .slds-form-element_stacked {
  display: block;

  &:not(.slds-form-element_readonly) {
    margin-bottom: $spacing-x-small;
  }

  // When not editing, view mode, add some buffer to the form element
  &:not(.slds-is-editing) {
    padding: 0 $spacing-xx-small;
  }

  // Handle nested form elements due to slotting
  .slds-form-element {
    padding: 0;
    margin-bottom: 0;
  }

  // If form element doesn't have a size modifier, make sure it takes up 100% of the parents width
  &:not([class*="slds-size"]) {
    width: 100%;
    flex-basis: 100%;
  }

  // Make sure checkbox and radio elements always stacked in fieldsets
  .slds-checkbox,
  .slds-radio {
    display: block; // Override display: inline-block found on checkbox/radio
  }

  .slds-form-element__label,
  .slds-form-element__control {
    border-bottom: 0; // Remove border when using legacy version of slds-form-element
    padding-left: 0;
  }

  .slds-form-element__control {
    width: 100%;
    flex-basis: 100%;
    clear: left;

    @include rtl() {
      /*! @noflip */
      clear: right;
    }
  }

  .slds-form-element__icon {
    float: none;
    padding-top: $spacing-xx-small;
  }
}
